// The C++ projector against golden outputs of the pinned Python projector (hermes-vcc-engine
// 31ee4fe7), generated by tools/bench/vcc_golden.py into tests/fixtures/vcc.
#include "runtime/engine/compaction/vcc_projector.h"

#include <nlohmann/json.hpp>

#include <algorithm>
#include <cstddef>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <iterator>
#include <regex>
#include <sstream>
#include <string>
#include <vector>

namespace {

namespace fs         = std::filesystem;
namespace compaction = ninfer::runtime::compaction;

constexpr const char* kUpstreamCommit = "31ee4fe7ef3e3f6c67dadfd45ebc1a3cb9773f95";

int check(bool condition, const std::string& message) {
    if (condition) { return 0; }
    std::cerr << "FAIL: " << message << '\n';
    return 1;
}

std::string read_file(const fs::path& path) {
    std::ifstream in(path, std::ios::binary);
    return {std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>()};
}

// NINFER_VCC_FIXTURE_DIR runs the golden comparison on another set, such as the random fixtures
// `vcc_golden.py --fuzz N --out DIR` writes.
const char* fixture_override() { return std::getenv("NINFER_VCC_FIXTURE_DIR"); }

fs::path fixture_dir() {
    if (const char* dir = fixture_override(); dir != nullptr && *dir != 0) { return dir; }
    return fs::path(NINFER_SOURCE_DIR) / "tests" / "fixtures" / "vcc";
}

ninfer::ChatRole role_from(const std::string& name) {
    if (name == "system") { return ninfer::ChatRole::System; }
    if (name == "developer") { return ninfer::ChatRole::Developer; }
    if (name == "user") { return ninfer::ChatRole::User; }
    if (name == "assistant") { return ninfer::ChatRole::Assistant; }
    if (name == "tool") { return ninfer::ChatRole::Tool; }
    throw std::runtime_error("unknown role " + name);
}

std::vector<ninfer::ChatMessage> messages_from(const nlohmann::json& fixture) {
    std::vector<ninfer::ChatMessage> out;
    for (const auto& m : fixture.at("messages")) {
        ninfer::ChatMessage msg;
        msg.role = role_from(m.at("role").get<std::string>());
        for (const auto& p : m.value("parts", nlohmann::json::array())) {
            ninfer::MessagePart part;
            if (p.at("kind") == "text") {
                part.kind = ninfer::MessagePartKind::Text;
                part.text = p.at("text").get<std::string>();
            } else {
                part.kind       = ninfer::MessagePartKind::Media;
                part.media.kind = p.value("media_kind", "image") == "video" ? ninfer::MediaKind::Video
                                                                             : ninfer::MediaKind::Image;
            }
            msg.parts.push_back(std::move(part));
        }
        for (const auto& c : m.value("tool_calls", nlohmann::json::array())) {
            msg.tool_calls.push_back({c.at("id").get<std::string>(), c.at("name").get<std::string>(),
                                      c.at("arguments_json").get<std::string>()});
        }
        msg.tool_call_id      = m.value("tool_call_id", "");
        msg.reasoning_content = m.value("reasoning_content", "");
        out.push_back(std::move(msg));
    }
    return out;
}

std::size_t code_points(const std::string& s) {
    return static_cast<std::size_t>(
        std::count_if(s.begin(), s.end(), [](char c) { return (static_cast<unsigned char>(c) & 0xC0) != 0x80; }));
}

bool valid_utf8(const std::string& s) {
    std::size_t i = 0;
    while (i < s.size()) {
        const auto b = static_cast<unsigned char>(s[i]);
        std::size_t n = b < 0x80 ? 1 : (b >> 5) == 6 ? 2 : (b >> 4) == 14 ? 3 : (b >> 3) == 30 ? 4 : 0;
        if (n == 0 || i + n > s.size()) { return false; }
        for (std::size_t k = 1; k < n; ++k) {
            if ((static_cast<unsigned char>(s[i + k]) & 0xC0) != 0x80) { return false; }
        }
        i += n;
    }
    return true;
}

std::string first_difference(const std::string& got, const std::string& want) {
    std::size_t i = 0;
    while (i < got.size() && i < want.size() && got[i] == want[i]) { ++i; }
    const std::size_t from = i > 80 ? i - 80 : 0;
    std::ostringstream os;
    os << "first difference at byte " << i << " (got " << got.size() << " bytes, want " << want.size()
       << ")\n  got:  ..." << got.substr(from, 160) << "\n  want: ..." << want.substr(from, 160);
    return os.str();
}

struct Fixture {
    std::string name;
    nlohmann::json json;
    std::vector<ninfer::ChatMessage> messages;
};

std::vector<Fixture> load_fixtures() {
    std::vector<Fixture> out;
    for (const auto& entry : fs::directory_iterator(fixture_dir())) {
        if (entry.path().extension() != ".json") { continue; }
        Fixture f;
        f.name     = entry.path().stem().string();
        f.json     = nlohmann::json::parse(read_file(entry.path()));
        f.messages = messages_from(f.json);
        out.push_back(std::move(f));
    }
    std::sort(out.begin(), out.end(), [](const Fixture& a, const Fixture& b) { return a.name < b.name; });
    return out;
}

const Fixture* find(const std::vector<Fixture>& fixtures, const std::string& name) {
    for (const auto& f : fixtures) {
        if (f.name == name) { return &f; }
    }
    return nullptr;
}

// Projector.Golden: every case equals its Python output byte for byte.
int test_golden(const std::vector<Fixture>& fixtures, std::size_t min_cases) {
    int failures = 0;
    std::size_t cases = 0;
    for (const auto& f : fixtures) {
        for (const auto& c : f.json.at("cases")) {
            const std::string stem = f.name + "." + c.at("id").get<std::string>();
            const fs::path expected_path = fixture_dir() / (stem + ".expected.txt");
            const fs::path meta_path     = fixture_dir() / (stem + ".meta");
            failures += check(fs::exists(expected_path) && fs::exists(meta_path), stem + ": missing golden files");
            if (!fs::exists(expected_path) || !fs::exists(meta_path)) { continue; }
            const auto meta = nlohmann::json::parse(read_file(meta_path));
            failures += check(meta.at("commit") == kUpstreamCommit, stem + ": golden not from the pinned commit");
            const std::string got = compaction::project_transcript(
                f.messages, c.at("first").get<std::size_t>(), c.at("last").get<std::size_t>(),
                c.at("budget_chars").get<std::size_t>());
            const std::string want = read_file(expected_path);
            failures += check(got == want, stem + ": " + first_difference(got, want));
            ++cases;
        }
    }
    failures += check(cases >= min_cases, "expected at least " + std::to_string(min_cases) +
                                              " golden cases, found " + std::to_string(cases));
    std::cout << "golden cases: " << cases << '\n';
    return failures;
}

// Projector.Deterministic: same input, same bytes, also from an independent copy of the messages.
int test_deterministic(const std::vector<Fixture>& fixtures) {
    int failures = 0;
    for (const char* name : {"agent_claude", "upstream_long_session_80", "edge_results"}) {
        const Fixture* f = find(fixtures, name);
        failures += check(f != nullptr, std::string("fixture missing: ") + name);
        if (f == nullptr) { continue; }
        const std::vector<ninfer::ChatMessage> copy = messages_from(f->json);
        for (std::size_t budget : {700U, 6000U}) {
            const std::string a = compaction::project_transcript(f->messages, 0, f->messages.size(), budget);
            const std::string b = compaction::project_transcript(f->messages, 0, f->messages.size(), budget);
            const std::string c = compaction::project_transcript(copy, 0, copy.size(), budget);
            failures += check(a == b && b == c, std::string(name) + ": projection is not deterministic");
        }
    }
    return failures;
}

// Projector.RespectsBudget: never more than max(200, budget) code points, always valid UTF-8.
int test_respects_budget(const std::vector<Fixture>& fixtures) {
    int failures = 0;
    for (const auto& f : fixtures) {
        for (std::size_t budget : {0U, 200U, 201U, 333U, 500U, 1200U, 4000U, 20000U}) {
            const std::string out = compaction::project_transcript(f.messages, 0, f.messages.size(), budget);
            const std::size_t limit = std::max<std::size_t>(200, budget);
            failures += check(code_points(out) <= limit, f.name + ": " + std::to_string(code_points(out)) +
                                                             " code points over budget " + std::to_string(budget));
            failures += check(valid_utf8(out), f.name + ": output is not valid UTF-8");
        }
    }
    return failures;
}

// [#N] tags name absolute indices inside the summarised region.
int test_refs_are_absolute(const std::vector<Fixture>& fixtures) {
    int failures = 0;
    const Fixture* f = find(fixtures, "agent_hermes");
    failures += check(f != nullptr, "fixture missing: agent_hermes");
    if (f == nullptr) { return failures; }
    const std::size_t first = 40, last = 90;
    const std::string out   = compaction::project_transcript(f->messages, first, last, 100000);
    const std::regex ref(R"(\[#(\d+)\])");
    std::size_t refs = 0;
    for (auto it = std::sregex_iterator(out.begin(), out.end(), ref); it != std::sregex_iterator(); ++it) {
        const std::size_t n = std::stoul((*it)[1].str());
        failures += check(n >= first && n < last, "ref [#" + std::to_string(n) + "] outside the region");
        ++refs;
    }
    failures += check(refs > 20, "too few refs in the projection");
    failures += check(out.find("[#40]") != std::string::npos || out.find("[#41]") != std::string::npos,
                      "region start is not referenced");
    // An empty or out-of-range region still renders the header sections.
    const std::string empty = compaction::project_transcript(f->messages, 10, 10, 1000);
    failures += check(empty.rfind("## Historical Task Snapshot\nNone.", 0) == 0, "empty region header");
    const std::string clamped = compaction::project_transcript(f->messages, 5, 1u << 20, 1000);
    failures += check(clamped == compaction::project_transcript(f->messages, 5, f->messages.size(), 1000),
                      "last past the end is not clamped");
    return failures;
}

// Bytes that are not UTF-8 decode to U+FFFD instead of failing.
int test_invalid_utf8() {
    ninfer::ChatMessage msg;
    msg.role = ninfer::ChatRole::User;
    msg.parts.push_back({ninfer::MessagePartKind::Text, std::string("bad \xff\xfe bytes \xc3 and \xed\xa0\x80 end"), {}});
    const std::vector<ninfer::ChatMessage> messages{msg};
    const std::string out = compaction::project_transcript(messages, 0, 1, 1000);
    int failures          = check(valid_utf8(out), "invalid UTF-8 input produced invalid output");
    failures += check(out.find("bad \xef\xbf\xbd\xef\xbf\xbd bytes") != std::string::npos, "invalid bytes not replaced");
    return failures;
}

} // namespace

int main() {
    int failures = 0;
    try {
        const std::vector<Fixture> fixtures = load_fixtures();
        if (const char* dir = fixture_override(); dir != nullptr && *dir != 0) {
            failures += test_golden(fixtures, 1);
            failures += test_respects_budget(fixtures);
            std::cerr << (failures == 0 ? "" : "FAIL ") << "override set " << dir << '\n';
            return failures == 0 ? 0 : 1;
        }
        failures += check(fixtures.size() >= 20, "too few fixtures in " + fixture_dir().string());
        failures += test_golden(fixtures, 50);
        failures += test_deterministic(fixtures);
        failures += test_respects_budget(fixtures);
        failures += test_refs_are_absolute(fixtures);
        failures += test_invalid_utf8();
    } catch (const std::exception& e) {
        std::cerr << "FAIL: exception: " << e.what() << '\n';
        ++failures;
    }
    if (failures != 0) {
        std::cerr << failures << " failure(s)\n";
        return 1;
    }
    std::cout << "ninfer_vcc_projector_test passed\n";
    return 0;
}
